#!/usr/bin/env node
/**
 * harness.js — Evaluation harness for consulting-slide-quality skill
 *
 * Tests whether the skill produces correctly structured outputs for both:
 *   - Excalidraw wireframes (generated deterministically via generate-wireframe.js)
 *   - open-slide React components (generated by an agent following the skill)
 *
 * Modes:
 *   node harness.js generate     — generate all Excalidraw .excalidraw files from prompts
 *   node harness.js prompts      — print prompts formatted for agent input (open-slide generation)
 *   node harness.js validate     — validate all results in results/ against structural rules
 *   node harness.js report       — print a summary report of all results
 *
 * Usage:
 *   cd ~/.agents/skills/consulting-slide-quality/eval
 *   node harness.js generate     # → writes results/*.excalidraw
 *   node harness.js prompts      # → copy each prompt to agent, save .tsx to results/<id>.tsx
 *   node harness.js validate     # → checks all results, exits nonzero if failures
 */

'use strict';
const fs   = require('fs');
const path = require('path');
const cp   = require('child_process');

const PROMPTS_FILE   = path.join(__dirname, 'prompts.jsonl');
const RESULTS_DIR    = path.join(__dirname, 'results');
const GENERATOR      = path.join(__dirname, '../scripts/generate-wireframe.js');

// ── Load prompts ─────────────────────────────────────────────────────────────
function loadPrompts() {
  return fs.readFileSync(PROMPTS_FILE, 'utf8')
    .split('\n').filter(Boolean)
    .map(line => JSON.parse(line));
}

// ── MODE: generate ───────────────────────────────────────────────────────────
function cmdGenerate() {
  const prompts = loadPrompts();
  let ok = 0, skip = 0, fail = 0;

  prompts.forEach(p => {
    if (!p.wireframe) {
      console.log(`⚠ SKIP  ${p.id} — no wireframe config (expected: ${p.notes || p.expected_slide_type})`);
      skip++; return;
    }

    const input = JSON.stringify(p.wireframe);
    const outPath = path.join(RESULTS_DIR, p.id + '.excalidraw');

    try {
      const result = cp.execSync(`echo '${input.replace(/'/g, "\\'")}' | node "${GENERATOR}"`, {
        encoding: 'utf8', timeout: 10000,
      });
      fs.writeFileSync(outPath, result);
      const parsed = JSON.parse(result);
      console.log(`✓ OK    ${p.id} → ${p.id}.excalidraw (${parsed.elements.length} elements)`);
      ok++;
    } catch (e) {
      console.error(`✗ FAIL  ${p.id}: ${e.message.slice(0, 120)}`);
      fail++;
    }
  });

  console.log(`\nGenerate: ${ok} ok, ${skip} skipped, ${fail} failed`);
  process.exit(fail > 0 ? 1 : 0);
}

// ── MODE: prompts ─────────────────────────────────────────────────────────────
function cmdPrompts() {
  const prompts = loadPrompts();
  const divider = '─'.repeat(72);

  console.log(`
┌─────────────────────────────────────────────────────────────────────┐
│  OPEN-SLIDE EVAL PROMPTS — consulting-slide-quality skill           │
│  For each prompt below:                                             │
│    1. Read the skill (SKILL.md)                                     │
│    2. Classify the slide type per Section 1                        │
│    3. Generate open-slide index.tsx conforming to the skill         │
│    4. Save the output to eval/results/<id>.tsx                      │
│    5. Run: node harness.js validate                                 │
└─────────────────────────────────────────────────────────────────────┘`);

  prompts.forEach((p, i) => {
    console.log(`\n${divider}`);
    console.log(`PROMPT ${i + 1}/${prompts.length}  id: ${p.id}  expected: ${p.expected_slide_type}`);
    console.log(divider);
    console.log(`${p.description}`);
    if (p.notes) console.log(`\n⚠ Design note: ${p.notes}`);
    console.log(`\nSave output to: eval/results/${p.id}.tsx`);
  });

  console.log(`\n${divider}`);
  console.log('After generating all .tsx files: node harness.js validate');
}

// ── Validators ────────────────────────────────────────────────────────────────

function validateExcalidraw(id, filePath) {
  const errors = [];
  let data;
  try {
    data = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (e) {
    return [{ rule: 'parse', error: 'Invalid JSON: ' + e.message }];
  }

  if (data.type !== 'excalidraw') errors.push({ rule: 'envelope', error: 'Missing type:"excalidraw"' });
  if (!Array.isArray(data.elements)) errors.push({ rule: 'elements', error: 'Missing elements array' });

  const els = data.elements || [];

  // Must have a slide bounds rectangle
  const solidRects = els.filter(e => e.type === 'rectangle' && e.fillStyle === 'solid');
  if (solidRects.length === 0) errors.push({ rule: 'slide-bounds', error: 'No solid rectangle (slide bounds) found' });

  // Must have at least one text element
  const textEls = els.filter(e => e.type === 'text');
  if (textEls.length === 0) errors.push({ rule: 'text', error: 'No text elements found' });

  // No text should be positioned inside the no-fly zone (within MARGIN of edges)
  const MARGIN = 120;
  const CW = 1920, CH = 1080;
  textEls.forEach(t => {
    if (t.x < MARGIN - 10 || t.y < MARGIN - 10) {
      // Allow annotation labels outside the slide (negative y)
      if (t.y >= 0) errors.push({ rule: 'no-fly-zone', error: `Text "${t.text?.slice(0,30)}" at (${t.x},${t.y}) is inside no-fly zone` });
    }
  });

  // Must have a dominant text element (hero) — font size ≥ 56px
  const heroEls = textEls.filter(t => t.fontSize >= 56);
  if (heroEls.length === 0) errors.push({ rule: 'hierarchy', error: 'No hero text element (fontSize ≥ 56) found' });

  // Should not have more than 5 bullet-like text elements at body size (hint for density)
  const bodyEls = textEls.filter(t => t.fontSize >= 28 && t.fontSize < 56);
  if (bodyEls.length > 7) errors.push({ rule: 'density', error: `${bodyEls.length} body-size text elements (> 7 suggests high density — check slide count)` });

  return errors;
}

function validateTsx(id, filePath) {
  const errors = [];
  let src;
  try { src = fs.readFileSync(filePath, 'utf8'); } catch (e) {
    return [{ rule: 'read', error: 'Cannot read file: ' + e.message }];
  }

  if (!src.includes('export default')) errors.push({ rule: 'file-contract', error: 'Missing export default (Page[] required)' });
  if (!src.includes('export const meta')) errors.push({ rule: 'file-contract', error: 'Missing export const meta' });
  if (src.includes('overflow: auto') || src.includes("overflow: 'auto'") || src.includes('overflow: scroll')) {
    errors.push({ rule: 'no-overflow', error: 'overflow:auto/scroll detected — canvas does not scroll' });
  }

  // Check for no-fly zone: padding should be ≥ 96
  const paddingMatches = src.match(/padding[^,;]*?(\d+)/g) || [];
  const smallPaddings = paddingMatches.filter(m => {
    const nums = m.match(/\d+/g) || [];
    return nums.some(n => parseInt(n) < 96 && parseInt(n) > 0);
  });
  if (smallPaddings.length > 0) {
    errors.push({ rule: 'no-fly-zone', error: 'Possible padding below 96px — verify no-fly zone is respected: ' + smallPaddings.slice(0,2).join(', ') });
  }

  // Check that font sizes are above the floor
  const fontSizes = [...src.matchAll(/fontSize[^,;]*?(\d+)/g)].map(m => parseInt(m[1])).filter(n => n > 0);
  const tooSmall = fontSizes.filter(n => n < 28 && n > 8); // ignore things like strokeWidth
  if (tooSmall.length > 0) {
    errors.push({ rule: 'type-floor', error: `fontSize below 28px floor: ${tooSmall.join(', ')}` });
  }

  return errors;
}

// ── MODE: validate ────────────────────────────────────────────────────────────
function cmdValidate() {
  const prompts = loadPrompts();
  const results = [];
  let totalErrors = 0;

  prompts.forEach(p => {
    const excalidrawPath = path.join(RESULTS_DIR, p.id + '.excalidraw');
    const tsxPath        = path.join(RESULTS_DIR, p.id + '.tsx');

    const row = { id: p.id, type: p.expected_slide_type, excalidraw: null, tsx: null };

    if (fs.existsSync(excalidrawPath)) {
      const errs = validateExcalidraw(p.id, excalidrawPath);
      row.excalidraw = errs.length === 0 ? 'PASS' : errs;
      totalErrors += errs.length;
    } else {
      row.excalidraw = p.wireframe ? 'MISSING (run: node harness.js generate)' : 'N/A (no wireframe — intentional)';
    }

    if (fs.existsSync(tsxPath)) {
      const errs = validateTsx(p.id, tsxPath);
      row.tsx = errs.length === 0 ? 'PASS' : errs;
      totalErrors += errs.length;
    } else {
      row.tsx = 'MISSING (run: node harness.js prompts, then generate .tsx files)';
    }

    results.push(row);
  });

  // Report
  results.forEach(r => {
    const excStatus = r.excalidraw === 'PASS' ? '✓' : (Array.isArray(r.excalidraw) ? '✗' : '–');
    const tsxStatus = r.tsx === 'PASS' ? '✓' : (Array.isArray(r.tsx) ? '✗' : '–');
    console.log(`[${excStatus} excalidraw] [${tsxStatus} tsx] ${r.id} (${r.type})`);
    if (Array.isArray(r.excalidraw)) r.excalidraw.forEach(e => console.log(`   ✗ excalidraw/${e.rule}: ${e.error}`));
    if (Array.isArray(r.tsx))        r.tsx.forEach(e => console.log(`   ✗ tsx/${e.rule}: ${e.error}`));
  });

  console.log(`\n${totalErrors === 0 ? '✓ All checks passed' : `✗ ${totalErrors} error(s) found`}`);
  process.exit(totalErrors > 0 ? 1 : 0);
}

// ── MODE: report ──────────────────────────────────────────────────────────────
function cmdReport() {
  const prompts = loadPrompts();
  const ts = new Date().toISOString().replace('T', ' ').slice(0, 19);
  console.log(`\n═══ consulting-slide-quality EVAL REPORT  [${ts}] ═══\n`);
  prompts.forEach(p => {
    const ex = path.join(RESULTS_DIR, p.id + '.excalidraw');
    const tx = path.join(RESULTS_DIR, p.id + '.tsx');
    const exStatus = fs.existsSync(ex) ? '✓ generated' : '– missing';
    const txStatus = fs.existsSync(tx) ? '✓ generated' : '– missing';
    console.log(`${p.id.padEnd(14)} expected:${String(p.expected_slide_type).padEnd(16)} excalidraw:${exStatus}  tsx:${txStatus}`);
  });
  console.log(`\nRun "node harness.js validate" for detailed structural checks.`);
}

// ── Dispatch ──────────────────────────────────────────────────────────────────
const [,, mode] = process.argv;
switch (mode) {
  case 'generate': cmdGenerate(); break;
  case 'prompts':  cmdPrompts();  break;
  case 'validate': cmdValidate(); break;
  case 'report':   cmdReport();   break;
  default:
    console.log('Usage: node harness.js [generate|prompts|validate|report]');
    process.exit(1);
}
